  const meta = {
    job_id: jobId,
    specialty: SPECIALTY_SLUG,
    agent_id: AGENT_ID,
    output_chars: outputText.length,
    outcome: 'customer_intelligence_emitted',
  };
  await xano.markSignalProcessed(signal.id, 'customer_intelligence_emitted', meta);
  log('customer_intelligence_emitted', meta);

  return { success: true, action: meta.outcome, job_id: jobId, agent_id: AGENT_ID };
